from django.db import models
from django.contrib.auth.models import AbstractBaseUser, PermissionsMixin, BaseUserManager
from django.core.exceptions import ValidationError
from django.utils import timezone
from django.core.validators import MinValueValidator


class UserManager(BaseUserManager):
    use_in_migrations = True

    def create_user(self, email, password=None, **extra_fields):
        if not email:
            raise ValueError("The Email field must be set")
        email = self.normalize_email(email)
        user = self.model(email=email, **extra_fields)
        user.set_password(password)
        user.save(using=self._db)
        return user

    def create_superuser(self, email, password=None, **extra_fields):
        extra_fields.setdefault('is_staff', True)
        extra_fields.setdefault('is_superuser', True)

        if extra_fields.get('is_staff') is not True:
            raise ValueError('Superuser must have is_staff=True.')
        if extra_fields.get('is_superuser') is not True:
            raise ValueError('Superuser must have is_superuser=True.')

        return self.create_user(email, password, **extra_fields)


class User(AbstractBaseUser, PermissionsMixin):
    REQUIRED_FIELDS = ['full_name']
    USERNAME_FIELD = 'email'

    email = models.EmailField(unique=True)
    full_name = models.CharField(max_length=255)
    username = None
    is_staff = models.BooleanField(default=False)
    is_active = models.BooleanField(default=True)

    objects = UserManager()

    def __str__(self):
        return self.email

    def get_full_name(self):
        return self.full_name

    def get_short_name(self):
        return self.full_name.split(' ')[0] if self.full_name else self.email


class Book(models.Model):
    class Cover(models.TextChoices):
        HARD = 'HARD', 'Hard'
        SOFT = 'SOFT', 'Soft'

    title = models.CharField(max_length=255)
    author = models.CharField(max_length=255)
    cover = models.CharField(max_length=4, choices=Cover.choices, default=Cover.SOFT)
    inventory = models.PositiveIntegerField(default=1)
    daily_fee = models.DecimalField(max_digits=10, decimal_places=2, validators=[MinValueValidator(0)])

    class Meta:
        ordering = ['title']

    def __str__(self):
        return self.title


class Borrowing(models.Model):
    book = models.ForeignKey(Book, on_delete=models.CASCADE, related_name='borrowings')
    user = models.ForeignKey(User, on_delete=models.CASCADE, related_name='borrowings')
    borrow_date = models.DateField(default=timezone.now)
    expected_return_date = models.DateField()
    actual_return_date = models.DateField(null=True, blank=True)
    total_price = models.DecimalField(max_digits=10, decimal_places=2, default=0)

    class Meta:
        ordering = ['-borrow_date']
        constraints = [
            models.CheckConstraint(
                check=models.Q(expected_return_date__gte=models.F('borrow_date')),
                name='expected_return_date_after_borrow_date'
            ),
            models.CheckConstraint(
                check=models.Q(actual_return_date__isnull=True) | models.Q(actual_return_date__gte=models.F('borrow_date')),
                name='actual_return_date_after_borrow_date'
            ),
        ]

    def clean(self):
        if self.book_id:
            self.validate_borrowing(self.book.inventory)
        if self.expected_return_date and self.borrow_date and self.expected_return_date < self.borrow_date:
            raise ValidationError({'expected_return_date': 'Expected return date must be on or after borrow date.'})
        if self.actual_return_date and self.borrow_date and self.actual_return_date < self.borrow_date:
            raise ValidationError({'actual_return_date': 'Actual return date cannot be before borrow date.'})
        if not self.pk and self.book_id and self.book.inventory <= 0:
            raise ValidationError('Book is out of stock.')
        if not self.total_price and self.book_id:
            days = (self.expected_return_date - self.borrow_date).days
            self.total_price = days * self.book.daily_fee

    def validate_borrowing(self, inventory: int):
        if inventory <= 0:
            raise ValidationError('Book is out of stock.')

    def save(self, *args, **kwargs):
        self.full_clean()
        super().save(*args, **kwargs)

    def __str__(self):
        return f"{self.user} - {self.book} ({self.borrow_date})"


